<script lang="ts">
 import {untrack} from 'svelte';
 import {api} from './api';
 let {company,view,onopen,revision=0,canPlan=false}:{company:string;view:string;onopen:(id:number)=>void;revision:number;canPlan:boolean}=$props();
 let result:any=$state(null),search=$state(''),stage=$state(''),page=$state(1),busy=$state(false),error=$state(''),generation=0;
 let from=$state(''),to=$state(''),group=$state(''),resource=$state(''),brand=$state(''),fit=$state(''),caps:any=$state([]),selection:any[]=$state([]),start=$state(new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'})),target=$state(''),preview:any=$state(null),dragIndex=-1;
 const stages=['Ready','Pattern ready','Cut','Allocated','Sewing','Sewn','Finishing','Awaiting audit','Audit','Approved','Rework','Rejected','With merchant','Showroom','Handed over'];
 const cols=[['request_date','Issue date'],['product','Product'],['brand','Brand'],['pattern_status','Pattern type'],['sample_type','Sample type'],['buyer_po','PO'],['est','Euro style'],['fit','Block / fit'],['spec_reference','Specification'],['buyer_required_date','Required date'],['plan_date','Plan date']];
 const prodCols=[['file_clearance','File clearance'],['fabric_update_date','Fabric ready'],['trims_update_date','Trims ready'],['pattern_plan_date','Pattern plan'],['pattern_actual','Pattern actual'],['cut_actual','Cut'],['allocation_actual','Allocation'],['sample_maker','Sample tailor'],['sewing_plan_date','Sewing plan'],['sewing','Sewing'],['finishing','Finishing'],['audit','Audit'],['audited_by','Auditor'],['merchant_actual','Merchant / showroom handover'],['handover_actual','Final handover'],['awb','AWB / shipment'],['audit_result','Pass / fail'],['buyer_result','Buyer pass / fail'],['buyer_comments','Buyer comments'],['readiness_note','Remarks']];
 async function load(){const n=++generation;busy=true;error='';try{const r=await api('/sample-planning?'+new URLSearchParams({company,view,search,stage,page:String(page),from,to,resource,group,brand,fit,unplanned:String(view==='plan')}));if(n===generation){result=r;caps=(await api('/sample-capacities')).records.filter((c:any)=>String(c.company_id)===company)}}catch(e){if(n===generation)error=(e as Error).message}finally{if(n===generation)busy=false}}
 $effect(()=>{company;view;revision;untrack(()=>{page=1;search='';stage='';resource='';selection=[];preview=null;load()})});
 function stageText(r:any,k:string){const p=r.production;if(['sewing','finishing','audit'].includes(k)){if(p[k+'_actual']&&!(r.status==='Rework'&&k==='sewing'))return (k==='audit'?p.audit_result+' · ':'Completed · ')+day(p[k+'_actual']);if(p[k+'_started'])return 'In progress · '+day(p[k+'_started']);return 'Pending'}return k.endsWith('_actual')||k.endsWith('_started')?day(p[k]):p[k]||'—'}
 function tone(r:any,k:string){const p=r.production;if(r.status==='Handed over')return 'complete';if(k==='file_clearance')return p[k]==='Clear'?'ready':p[k]==='Missing'?'missing':'pending';if(['sewing','finishing','audit'].includes(k)){if(r.status==='Rework'&&k==='sewing')return 'missing';if(p[k+'_actual'])return k==='audit'&&p.audit_result!=='Approved'?'missing':'ready';return p[k+'_started']?'running':'pending'}return p[k]?'ready':''}
 function day(value:any){return !value?'—':String(value).includes('T')?new Date(String(value)).toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}):String(value).slice(0,10)}
 function late(r:any){const due=r.profile.buyer_required_date;if(!due)return null;const actual=r.production.handover_actual?day(r.production.handover_actual):result.today;return Math.round((Date.parse(actual)-Date.parse(due))/86400000)}

 function exportRows(){const values=[['Indent','Stage','Buyer','Buyer style','Merchant','Size','Colour','Fabric','Plan resource','Frozen plan date',...cols.map(c=>c[1]),...prodCols.map(c=>c[1])],...(result?.rows||[]).map((r:any)=>[r.id,r.status,r.buyer,r.profile.buyer_style,r.merchant,r.size,r.colour,r.fabric,r.resource,r.frozen_date,...cols.map(([k])=>r.profile[k]),...prodCols.map(([k])=>stageText(r,k))])];const csv='\ufeff'+values.map(row=>row.map((v:any)=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='sampling-'+view+'-page-'+page+'.csv';a.click();URL.revokeObjectURL(url)}
 function select(row:any,checked:boolean){preview=null;selection=checked?[...selection,row]:selection.filter(r=>r.id!==row.id)}
 function move(from:number,to:number){if(to<0||to>=selection.length||from===to)return;const next=[...selection];next.splice(to,0,next.splice(from,1)[0]);selection=next;preview=null}
 async function schedule(action:string){if(busy)return;busy=true;error='';try{const r=await api('/sample-schedule',{company_id:Number(company),resource:target,start_date:start,indents:selection.map(i=>({id:i.id,version:i.version})),action,token:preview?.token});if(action==='preview')preview=r;else{selection=[];preview=null;await load()}}catch(e){error=(e as Error).message;preview=null}finally{busy=false}}
</script>
<div class="filters"><label>Search indent, style, buyer or tailor<input bind:value={search} placeholder="Search the full register" onkeydown={e=>{if(e.key==='Enter'){page=1;load()}}}/></label><label>Stage<select bind:value={stage}><option value="">All stages</option>{#each stages as s}<option>{s}</option>{/each}</select></label><label>Required from<input type="date" bind:value={from}/></label><label>Required to<input type="date" bind:value={to}/></label><label>Group<select bind:value={group}><option value="">All products</option><option>General</option><option>Suits</option></select></label><label>Brand<input bind:value={brand}/></label><label>Block / fit<input bind:value={fit}/></label>{#if view!=='plan'}<label>Resource<select bind:value={resource}><option value="">All resources</option>{#each [...new Set(caps.map((c:any)=>c.resource))] as name}<option>{String(name)}</option>{/each}</select></label>{/if}<button class="button primary" disabled={busy} onclick={()=>{page=1;load()}}>Apply</button></div>
{#if error}<p class="form-error" role="alert">{error}</p>{/if}
<p class="chart-note">{view==='plan'?'Select unplanned garments, choose a resource, set priority, preview dates and freeze.':view==='live'?'Active garments awaiting final handover.':'Every approved garment, including completed and rejected indents.'} Scroll sideways for the full planning chart. Dates follow India time.</p>
<p class="legend"><span class="ready">Green: completed / ready</span><span class="running">Pink: in progress</span><span class="missing">Red: missing / rework</span><span class="complete">Yellow: final handover</span></p><div class="chart" aria-busy={busy}><table><thead><tr><th class="fixed">{view==='plan'?'Select / indent':'Indent'}</th><th>Frozen plan / resource</th><th>Stage</th><th>Buyer / style</th><th>Merchant</th><th>Size / colour</th><th>Fabric / alternate</th>{#each cols as [,title]}<th>{title}</th>{/each}<th>Early / late days</th>{#each prodCols as [,title]}<th>{title}</th>{/each}</tr></thead><tbody>{#each result?.rows||[] as r}<tr class:handed={r.status==='Handed over'}><td class="fixed">{#if view==='plan'&&canPlan}<input class="select-check" type="checkbox" aria-label={'Select indent '+r.id} checked={selection.some(i=>i.id===r.id)} disabled={!selection.some(i=>i.id===r.id)&&selection.length>=200} onchange={e=>select(r,e.currentTarget.checked)}/>{/if}<button class="text-button" onclick={()=>onopen(r.request_id)}>#{r.id}</button></td><td>{r.frozen_date||'Unplanned'}<small>{r.resource||''}</small></td><td><strong class:closed={r.status==='Handed over'}>{r.status}</strong></td><td>{r.buyer}<small>{r.profile.buyer_style}</small></td><td>{r.merchant}</td><td>{r.size} · {r.colour}<small>1 piece</small></td><td>{r.fabric}<small>{r.alternate_fabric?'Alternate: '+r.alternate_fabric:''}</small></td>{#each cols as [key]}<td>{r.profile[key]||'—'}</td>{/each}<td class:late={(late(r)||0)>0}>{late(r)===null?'—':late(r)===0?'On date':late(r)!>0?late(r)+' late':Math.abs(late(r)!)+(r.status==='Handed over'?' early':' days remaining')}</td>{#each prodCols as [key]}<td class={tone(r,key)}>{stageText(r,key)}</td>{/each}</tr>{:else}<tr><td colspan="36">{busy?'Loading planning chart…':'No indents match these filters.'}</td></tr>{/each}</tbody></table></div>
<div class="pager"><button class="button secondary" disabled={busy||!result?.rows.length} onclick={exportRows}>Export this page</button><span>{result?.total||0} indents · Page {page}</span><button class="button secondary" disabled={busy||page===1} onclick={()=>{page--;load()}}>Previous</button><button class="button secondary" disabled={busy||page*50>=(result?.total||0)} onclick={()=>{page++;load()}}>Next</button></div>
{#if view==='plan'&&canPlan}<section class="queue"><h3>Plan priority · {selection.length} selected</h3><p>Drag to reorder, or use the arrows. Dates respect fabric/trims availability, dated capacity, Sundays and holidays. Existing frozen bookings consume capacity first.</p>{#each selection as row,i (row.id)}<div class="queue-row" role="listitem" draggable="true" ondragstart={()=>dragIndex=i} ondragover={e=>e.preventDefault()} ondrop={e=>{e.preventDefault();move(dragIndex,i)}}><strong>{i+1}</strong><span>#{row.id} · {row.profile.buyer_style} · {row.size} · {row.colour}</span><button class="button secondary" aria-label={'Move indent '+row.id+' up'} disabled={i===0} onclick={()=>move(i,i-1)}>↑</button><button class="button secondary" aria-label={'Move indent '+row.id+' down'} disabled={i===selection.length-1} onclick={()=>move(i,i+1)}>↓</button><button class="text-button" onclick={()=>select(row,false)}>Remove</button></div>{/each}<label>Planning resource<select bind:value={target} onchange={()=>preview=null}><option value="">Choose resource</option>{#each [...new Set(caps.map((c:any)=>c.resource))] as name}<option>{String(name)}</option>{/each}</select></label><label>Start date<input type="date" bind:value={start} onchange={()=>preview=null}/></label>{#if !caps.length}<p>Open Capacity and ask Super Admin to enter the actual daily capacity.</p>{/if}<div class="queue-actions"><button class="button primary" disabled={busy||!company||!target||!selection.length} onclick={()=>schedule('preview')}>Preview plan dates</button>{#if preview}<button class="button primary" disabled={busy} onclick={()=>schedule('freeze')}>Freeze this plan</button>{/if}</div>{#if preview}<div class="chart"><table><thead><tr><th>Indent</th><th>Plan date</th><th>Required date</th><th>Delivery outlook</th></tr></thead><tbody>{#each preview.rows as row}<tr><td>#{row.id}</td><td>{row.plan_date}</td><td>{row.required_date}</td><td class:late={row.late}>{row.late?'After required date':'Within required date'}</td></tr>{/each}</tbody></table></div><p>Freezing records these dates in the master and removes selected garments from the unplanned queue.</p>{/if}</section>{/if}
<style>
 .filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin:20px 0}.filters label{display:grid;gap:7px;color:#142536;font-weight:700}.filters input,.filters select{padding:10px;border:1px solid #aebfc9;border-radius:7px;background:#eff5fa;min-height:42px;color:#101820}.chart-note{color:#374b5a}.chart{overflow:auto;max-height:65vh;border:1px solid #bdcdd5;border-radius:10px}table{border-collapse:separate;border-spacing:0;width:max-content;min-width:100%;font-size:14px}th,td{text-align:left;padding:12px 14px;border-bottom:1px solid #d2dce0;max-width:260px;min-width:110px;overflow-wrap:anywhere}th{position:sticky;top:0;background:#132b40;color:#fff;z-index:2;font-weight:700}td{background:#fff}tr:nth-child(even) td{background:#f1f6f8}.fixed{position:sticky;left:0;z-index:1;min-width:86px;box-shadow:2px 0 4px #10253510}th.fixed{z-index:3}small{display:block;margin-top:4px}.late{color:#a32026;font-weight:700}.closed{color:#16614c}.pager{display:flex;align-items:center;justify-content:flex-end;gap:10px;margin:16px 0}.pager span{margin-right:auto}
.legend{display:flex;gap:8px;flex-wrap:wrap}.legend span{padding:5px 9px;border-radius:5px}td.ready,.legend .ready{background:#dff1e5!important}td.running,.legend .running{background:#f9e1ee!important}td.missing,.legend .missing{background:#fce1de!important}td.complete,.legend .complete{background:#fff1c2!important}.select-check{width:18px;height:18px;display:block;margin-bottom:7px}.handed td{background:#fff1c2!important}.queue{padding:20px;border:1px solid #b6cbd3;border-radius:12px;background:#edf4f7;margin:20px 0}.queue-row{display:flex;gap:12px;align-items:center;background:#fff;padding:9px;margin:6px 0;border:1px solid #cedbe2;border-radius:6px}.queue-row span{flex:1}.queue-row button{min-width:40px;min-height:38px}.queue table{width:100%;margin:14px 0}.queue label{display:grid;gap:8px;margin:12px 0;font-weight:700}.queue input,.queue select{padding:10px;background:#eff5fa;color:#101820;border:1px solid #aebfc9;border-radius:7px}.queue-actions{display:flex;flex-wrap:wrap;gap:10px}
 </style>
